<section class="overflow-hidden rounded-2xl bg-white shadow-sm"><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-slate-500"><tr><th class="p-3">PO number</th><th class="p-3">Supplier</th><th class="p-3">Warehouse</th><th class="p-3">Date</th><th class="p-3 text-right">Total</th><th class="p-3">Status / actions</th></tr></thead><tbody>@forelse($orders as $o)<tr class="border-t align-top"><td class="p-3 font-semibold">{{ $o->order_number }}</td><td class="p-3">{{ $o->supplier?->name }}</td><td class="p-3">{{ $o->warehouse?->name }}</td><td class="p-3">{{ $o->order_date?->format('Y-m-d') }}</td><td class="p-3 text-right">K {{ number_format((float)$o->total,2) }}</td><td class="p-3"><div class="font-semibold capitalize">{{ str_replace('_',' ',$o->status) }}</div><div class="mt-2 flex flex-wrap gap-2">@if($o->status==='draft')<form method="POST" action="{{ route('procurement.orders.submit',$o->id) }}">@csrf<button class="rounded-full bg-blue-600 px-3 py-1.5 text-xs text-white">Submit</button></form>@elseif($o->status==='submitted')<form method="POST" action="{{ route('procurement.orders.approve',$o->id) }}">@csrf<button class="rounded-full bg-slate-900 px-3 py-1.5 text-xs text-white">Approve</button></form>@endif</div>
